import os, re, json

def load_demo_data():
    session_path = os.environ.get('RLM_SESSION_DIR', '')
    log_path = os.path.join(session_path, '../../sessions', os.path.basename(session_path) + '.jsonl')

    with open(log_path) as f:
        content = f.read().replace('\\n', '\n')

    demos = {}
    for match in re.finditer(r'(Demo pair \d+|Test input)\s*\((\d+)x(\d+)\):\n', content):
        key = match.group(1)
        height = int(match.group(2))
        width = int(match.group(3))
        demos[key] = [[int(x) for x in line.split()] for line in content[match.end():].split('\n')[:height]]

    return demos

demos = load_demo_data()

for name, grid in demos.items():
    # Find 1 and 2 positions
    pos1 = None
    pos2 = None
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                pos1 = (r, c)
            elif grid[r][c] == 2:
                pos2 = (r, c)
    print(f"{name}: 1@{pos1}, 2@{pos2}")

    # Find path cells (value 3)
    path_set = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 3:
                path_set.add((r, c))

    # Get path as list
    path = sorted(path_set)
    print(f"  Path ({len(path)} cells): {path[:5]}...{path[-5:] if len(path)>5 else ''}")

